try {
  const input = $input.first().json.content[0].text || "";

  if (typeof input !== "string") {
    throw new Error("Input must be a string");
  }

  const cleaned = input
    .replace(/"/g, "")                   // remove ALL double quotes
    .replace(/[!@#$%^&*()';\/\\]/g, "")  // remove other unwanted symbols
    .replace(/\n/g, " ")                 // replace new lines with space
    .replace(/\s+/g, " ")                // collapse multiple spaces
    .trim();

  return [
    {
      json: {
        cleaned_text: cleaned,
        success: true
      }
    }
  ];

} catch (error) {
  return [
    {
      json: {
        cleaned_text: null,
        success: false,
        error: error.message || "Unknown error"
      }
    }
  ];
}

const styles = [
  "Origin Story — Angus McBones recounts how he came to haunt the Scottish Highlands",
  "Adventure Tale — Angus embarks on a daring expedition in his safari outfit",
  "Military Honour — Angus reflects on battles fought and medals earned in his military uniform",
  "Highland Pride — Angus celebrates Scottish heritage in his hybrid kilt and blazer",
  "Mystery and Intrigue — Angus uncovers a dark secret hidden beneath the Scottish moors",
  "Comedy and Wit — Angus gets into a humorous situation that only a skeleton could survive",
  "Legendary Folklore — Angus retells an ancient Scottish legend with a twist"
];

const dayIndex = new Date().getDay(); // 0 = Sunday, 6 = Saturday
const style = styles[dayIndex % styles.length];
return [{ json: { style } }];

